delete from public.pruef_einheiten where thema_id = 17;

-- Lösungswege für die Forderungskarte (ohne Punkte). Upsert, damit gespeicherte Forderungen ihren Verweis behalten.
insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (7272, 17, 'Bedarfsgerechte Betreuungsplätze und Rechtsanspruch verlässlich sichern (Land)', 'Ein erfüllter Anspruch verbessert den Zugang direkt, setzt aber ausreichende Plätze und Personal voraus. Die Umsetzung hängt deshalb von regionaler Kapazität und Finanzierung ab.', 'gemischt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'land', null, true, 'blind'),
  (7273, 17, 'Genehmigungsverfahren für Kita-Ausbau beschleunigen (Land)', 'Kürzere Verfahren können den Ausbau erleichtern, schaffen aber weder Bauflächen noch Personal. Verwaltungsvereinfachungen sind innerhalb einer Wahlperiode realistisch.', 'offen', null, 'land', null, true, 'blind'),
  (7274, 17, 'Kita-Plätze bedarfsgerecht ausbauen, erhalten und sanieren (Land)', 'Zusätzliche und gesicherte Plätze wirken unmittelbar gegen Angebotslücken; der tatsächliche Effekt hängt von Personalverfügbarkeit und regionaler Planung ab. Investitionen und laufende Kosten begrenzen das Tempo.', 'belegt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'land', null, true, 'blind'),
  (7275, 17, 'Kita-Träger und Kindertagespflege bedarfsgerecht finanzieren (Land)', 'Eine verlässliche Finanzierung kann Plätze erhalten und Ausbau ermöglichen. Der Effekt hängt davon ab, ob Mittel zusätzlich bereitgestellt und tatsächlich für Kapazitäten eingesetzt werden.', 'gemischt', 'https://www.dji.de/themen/kinderbetreuung/kita-personalbedarf.html', 'land', null, true, 'blind'),
  (7276, 17, 'Kommunale Bedarfsplanung und flexible Angebotssteuerung stärken (Land)', 'Kleinräumige Planung kann Plätze besser an Bedarf und Bevölkerungsentwicklung anpassen. Sie behebt einen landesweiten Personal- oder Finanzmangel nicht allein.', 'gemischt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'land', null, true, 'blind'),
  (7277, 17, 'Flexible und ergänzende Betreuungsangebote ausbauen (Land)', 'Bedarfsgerechte Zeiten und Ersatzangebote können Versorgungslücken für Familien mit besonderen Arbeitszeiten abfedern. Personalbedarf, Nachfrage und Qualität begrenzen die flächendeckende Umsetzung.', 'gemischt', 'https://www.dji.de/themen/kinderbetreuung/eltern-wuenschen-sich-flexiblere-betreuungsangebote.html', 'land', null, true, 'blind'),
  (7278, 17, 'Kita-Betreuung rund um die Uhr anbieten (Land)', 'Nachtbetreuung hilft nur Familien mit entsprechendem Bedarf und löst die allgemeine Angebotslücke kaum. Der hohe Personal- und Organisationsaufwand erschwert eine Umsetzung in der Wahlperiode.', 'offen', null, 'land', null, true, 'blind'),
  (7279, 17, 'Betriebliche Kinderbetreuung fördern (Land)', 'Betriebskitas schaffen zusätzliche Plätze und können Arbeitszeiten besser abdecken. Sie erreichen nicht alle Familien und benötigen Personal sowie tragfähige Trägerfinanzierung.', 'offen', null, 'land', null, true, 'blind'),
  (7280, 17, 'Kommunen beim Ausbau wohnortnaher Betreuungsplätze unterstützen (Bund)', 'Investitionshilfen können zusätzliche Plätze und erreichbare Angebote ermöglichen. Die Wirkung hängt von kommunaler Planung, Kofinanzierung und verfügbarem Personal ab.', 'belegt', 'https://www.dji.de/themen/kinderbetreuung/kita-personalbedarf.html', 'bund', null, true, 'blind'),
  (7281, 17, 'Betriebliche Kinderbetreuung fördern und steuerlich unterstützen (Bund)', 'Anreize können zusätzliche betriebliche Plätze mobilisieren, besonders für Beschäftigte mit passenden Arbeitszeiten. Wie viele zusätzliche Plätze dadurch entstehen, ist für die konkrete Ausgestaltung unsicher.', 'offen', null, 'bund', null, true, 'blind'),
  (7282, 17, 'Kitagutschein automatisch versenden und Zugangshilfen bündeln (Land)', 'Eine automatische Information und Vermittlung kann administrative Hürden senken. Sie erhöht das Platzangebot nicht und hilft nur, wenn passende Plätze verfügbar sind.', 'gemischt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'land', null, true, 'blind'),
  (7283, 17, 'Kita-Platzvergabe transparent und digital organisieren (Land)', 'Transparente Verfahren können Mehrfachanmeldungen und ungerechte Zugänge reduzieren. Ein digitales System schafft selbst keine zusätzlichen Betreuungsplätze.', 'gemischt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'land', null, true, 'blind'),
  (7284, 17, 'Belegte Kita-Plätze für kurzfristigen Bedarf vorhalten (Land)', 'Reservierte Plätze können einzelne Zugangsprobleme abfedern, verringern aber die Zahl regulär verfügbarer Plätze. Der Nutzen hängt von lokaler Nachfrage und verlässlicher Finanzierung ab.', 'offen', null, 'land', null, true, 'blind'),
  (7285, 17, 'Über Kita-Leistungen innerhalb fester Frist entscheiden (Land)', 'Schnellere Bescheide erleichtern die Planung und beseitigen Verzögerungen im Verwaltungszugang. Sie schaffen keinen Platz, wenn das Angebot fehlt.', 'offen', null, 'land', null, true, 'blind'),
  (7286, 17, 'Personalschlüssel auf 1:3 in Krippen und 1:7,5 in Kindergärten verbessern (Land)', 'Die konkreten Zielwerte setzen direkt an der Personalausstattung an, die pädagogische Interaktionen ermöglicht. Die Verbesserung ist wirksam, erfordert angesichts des Fachkräftemangels aber zusätzliche Personal- und Finanzressourcen.', 'belegt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'land', null, true, 'blind'),
  (7287, 17, 'Tatsächliche Personal-Kind-Relation schrittweise verbessern (Land)', 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'belegt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'land', null, true, 'blind'),
  (7288, 17, 'Personalschlüssel in Krippen auf 1:4 und in Kindergärten auf 1:10 verbessern (Land)', 'Die Zielwerte verbessern die Personalausstattung gegenüber ungünstigen Ausgangslagen, bleiben aber hinter den fachlichen Empfehlungen zurück. Zusätzliches Personal ist nötig.', 'belegt', 'https://www.dji.de/themen/kinderbetreuung/plaetze-und-personalschluessel.html', 'land', null, true, 'blind'),
  (7289, 17, 'Personalschlüssel in Krippen auf 1:5 und in Kindergärten auf 1:13 verbessern (Land)', 'Die festen Stufen verbessern die Personalausstattung, bleiben aber deutlich hinter den fachlichen Empfehlungen von 1:3 und 1:7,5 zurück. Der Zeitplan ist bestimmt, das zusätzliche Personal muss bei Fachkräftemangel aber erst gewonnen werden.', 'belegt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'land', null, true, 'nicht_blind'),
  (7290, 17, 'Bundesweite Personal-Kind-Relation einschließlich Ausfallzeiten festlegen (Bund)', 'Einheitliche Mindeststandards können die Qualität und Berücksichtigung von Ausfällen stärken. Die Länder setzen sie um; Personalverfügbarkeit und Finanzierung bestimmen die tatsächliche Wirkung.', 'belegt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'bund', null, true, 'blind'),
  (7291, 17, 'Vergütung und Arbeitsbedingungen in Kitas verbessern (Land)', 'Bessere Bezahlung und Arbeitsbedingungen können die Attraktivität und Bindung von Fachkräften erhöhen. Der Fachkräftemangel und die Tarif- und Haushaltskosten begrenzen Geschwindigkeit und Reichweite.', 'gemischt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'land', null, true, 'blind'),
  (7292, 17, 'Tarifvergütung in Sozial- und Erziehungsdiensten refinanzieren (Bund)', 'Die Refinanzierung kann Trägern ermöglichen, tarifliche Löhne zu zahlen und Personal zu halten. Der Bund kann Kosten mittragen, aber die tatsächliche Personalgewinnung ist nicht garantiert.', 'gemischt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'bund', null, true, 'blind'),
  (7293, 17, 'Ausbildungskapazitäten erweitern und Qualifizierung erleichtern (Land)', 'Mehr Ausbildungsplätze, Praxisanteile und Quereinstiege können mittelfristig den Personalzugang verbessern. Fehlende Lehrkräfte, Räume und Ausbildungserfolg begrenzen den Zuwachs.', 'gemischt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'land', null, true, 'blind'),
  (7294, 17, 'Erzieherausbildung und Praxisphasen vergüten (Land)', 'Vergütung kann den Zugang zur Ausbildung erleichtern und die Zahl der Auszubildenden erhöhen. Ein unmittelbarer Effekt auf verfügbare Fachkräfte entsteht erst nach Ausbildungsabschluss.', 'gemischt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'land', null, true, 'blind'),
  (7295, 17, 'Ausbildung und Fachkräftegewinnung für Kitas fördern (Bund)', 'Bundesmittel für vergütete Ausbildung, Kapazitäten und Qualifizierung können den Ländern beim Aufbau des Personals helfen. Wirkung und Zeitbedarf hängen von Länderumsetzung und Ausbildungserfolg ab.', 'gemischt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'bund', null, true, 'blind'),
  (7296, 17, 'Verwaltungs- und Dokumentationsaufwand in Kitas reduzieren (Land)', 'Weniger unnötige Dokumentation kann Fachkräfte und Leitung entlasten. Freigesetzte Zeit ersetzt keine zusätzlichen Betreuungskräfte und hängt von einer sorgfältigen Auswahl der Pflichten ab.', 'offen', null, 'land', null, true, 'blind'),
  (7297, 17, 'Pädagogische Teams durch Verwaltungs- und Hauswirtschaftskräfte entlasten (Land)', 'Zusätzliche Unterstützung kann pädagogischen Fachkräften mehr Zeit für Kinder geben. Sie benötigt weiteres Personal und verbessert nicht automatisch die Fachkraft-Kind-Relation.', 'offen', null, 'land', null, true, 'blind'),
  (7298, 17, 'Multiprofessionelle Teams und zusätzliche Förderung stärken (Land)', 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'gemischt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'land', null, true, 'blind'),
  (7299, 17, 'Kindertagespflege fair vergüten und verlässlich unterstützen (Land)', 'Faire Entgelte, Beratung und klare Vereinbarungen können Tagespflegepersonen halten und zusätzliche Plätze ermöglichen. Die Zahl der erreichbaren Plätze bleibt von der Gewinnung und Bindung der Betreuungspersonen abhängig.', 'gemischt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'land', null, true, 'blind'),
  (7300, 17, 'Kita-Personalstandards auf Kindertagespflege übertragen (Land)', 'Eine bessere Personalausstattung kann die Betreuungsqualität erhöhen. Eine Übertragung ohne Einkommensverluste erfordert zusätzliche Finanzierung und muss zur Struktur der Tagespflege passen.', 'gemischt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'land', null, true, 'blind'),
  (7301, 17, 'Kindertagespflege bundesweit als Betreuungsangebot stärken (Bund)', 'Bundesunterstützung kann die Länder beim Erhalt und Ausbau ergänzender Betreuungsplätze unterstützen. Die konkrete Wirkung hängt von Umsetzung und dauerhafter Finanzierung vor Ort ab.', 'gemischt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'bund', null, true, 'blind'),
  (7302, 17, 'Kita-Beiträge landesweit abschaffen und Kosten dauerhaft finanzieren (Land)', 'Beitragsfreiheit entlastet Familien und kann die Nutzung besonders bei jüngeren Kindern erhöhen. Sie schafft zusätzliche Nachfrage und kann Mittel binden, die sonst für Qualität oder Plätze verfügbar wären.', 'gemischt', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'land', null, true, 'blind'),
  (7303, 17, 'Kita-Beiträge bundesweit abschaffen oder senken (Bund)', 'Geringere Beiträge entlasten Familien und können den Zugang erleichtern, beseitigen aber nicht alle Zusatzkosten. Mehr Nachfrage kann bei knappen Plätzen den Zugang erschweren, wenn der Ausbau nicht Schritt hält.', 'gemischt', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'bund', null, true, 'blind'),
  (7304, 17, 'Beitragsermäßigungen für Mehrkinderfamilien sichern (Land)', 'Ermäßigungen mindern die finanzielle Belastung größerer Familien, ohne die Kosten für alle Eltern abzuschaffen. Die Entlastung erreicht nur Familien, die die jeweilige Regelung nutzen.', 'gemischt', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'land', null, true, 'blind'),
  (7305, 17, 'Einkommensabhängige Kita-Beiträge bundesweit als Standard vorgeben (Bund)', 'Einkommensabhängige Beiträge können die Belastung gezielter bei Familien mit geringem Einkommen senken. Der Bund kann Vorgaben zur Staffelung machen, Höhe und Erhebung der Beiträge liegen aber bei Ländern und Kommunen; die Angebotsknappheit bleibt.', 'gemischt', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'bund', null, true, 'nicht_blind'),
  (7306, 17, 'Kinderbetreuungskosten steuerlich absetzen (Bund)', 'Steuerliche Abzüge können einen Teil der Kosten kompensieren. Die Entlastung ist geringer oder fehlt bei Familien mit niedriger Steuerlast und löst weder Platzmangel noch hohe laufende Beiträge direkt.', 'gemischt', 'https://www.oecd.org/en/publications/education-at-a-glance-2024_c00cad36-en.html', 'bund', null, true, 'blind'),
  (7307, 17, 'Personal- und Elternkosten der Kita-Qualität bedarfsgerecht finanzieren (Land)', 'Eine Finanzierung der tatsächlichen Kosten kann bessere Personalausstattung ermöglichen und Beitragsbelastungen begrenzen. Die Ausgabenhöhe und die Verteilung zwischen Land, Kommunen und Trägern sind anspruchsvoll.', 'gemischt', 'https://www.dji.de/themen/kinderbetreuung/plaetze-und-personalschluessel.html', 'land', null, true, 'blind'),
  (7308, 17, 'Kinderbetreuungskosten über ein Lebenschancen-BAföG mitfinanzieren (Bund)', 'Ein zweckgebundener Zuschuss kann einzelne Familien bei den Kosten entlasten. Seine Reichweite hängt von Anspruchshöhe und Zugang ab und beeinflusst das Platzangebot nicht.', 'offen', null, 'bund', null, true, 'blind'),
  (7309, 17, 'Landeserziehungsgeld für Kinder unter drei Jahren einführen (Land)', 'Ein Geldbetrag kann Familien finanziell entlasten, sichert aber keinen Kita-Platz und kann die Nachfrage nach Betreuung sogar senken. Die Kosten hängen von Anspruch und Leistungshöhe ab.', 'gemischt', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'land', null, true, 'blind'),
  (7310, 17, 'Mittagsverpflegung in Kitas kostenfrei anbieten (Land)', 'Kostenfreie Mahlzeiten senken einen Teil der Familienausgaben, lassen Elternbeiträge und weitere Zusatzkosten aber bestehen. Die Wirkung auf die Gesamtbelastung ist daher begrenzt.', 'offen', null, 'land', null, true, 'blind'),
  (7311, 17, 'Verpflichtende Zusatzbeiträge von Eltern verhindern (Land)', 'Das Verhindern verpflichtender Zusatzforderungen kann unerwartete Kosten begrenzen. Es senkt nicht automatisch die regulären Elternbeiträge und muss mit der Finanzierung zusätzlicher Leistungen vereinbar sein.', 'offen', null, 'land', null, true, 'blind'),
  (7312, 17, 'Mindestankündigungsfristen und Schlichtung bei Kita-Streiks einführen (Bund)', 'Vorankündigung und Schlichtung könnten Familien mehr Planungssicherheit geben. Sie verhindern weder krankheitsbedingte Ausfälle noch lösen sie Personalengpässe; arbeitsrechtliche Ausgestaltung ist anspruchsvoll.', 'offen', null, 'bund', null, true, 'blind'),
  (7313, 17, 'Zusätzliche Mittel zur kurzfristigen Personalsicherung bereitstellen (Land)', 'Zusätzliche Personalressourcen können Ausfälle auffangen und Betreuung stabilisieren. Eine dauerhafte Wirkung setzt verlässliche Finanzierung und verfügbare Fachkräfte voraus.', 'gemischt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'land', null, true, 'blind'),
  (7314, 17, 'Kita-Qualitätsmittel für Personal und Leitungszeit einsetzen (Land)', 'Zusätzliche pädagogische Leitungs- und Personalzeit kann die Arbeit in Einrichtungen verbessern. Die Wirkung hängt davon ab, dass Mittel zusätzlich und dauerhaft für qualifiziertes Personal eingesetzt werden.', 'gemischt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'land', null, true, 'blind'),
  (7315, 17, 'Betreuungsgehalt zur Entlastung und Senkung der Platznachfrage einführen (Bund)', 'Ein Betreuungsgehalt kann einzelne Familien finanziell entlasten, stellt aber keine bedarfsgerechte externe Betreuung sicher. Ob es die Platznachfrage dauerhaft senkt, ist unklar.', 'offen', null, 'bund', null, true, 'blind'),
  (7316, 17, 'Gesundheits-, Lärm- und Hitzeschutz für Kita-Beschäftigte verbessern (Land)', 'Bessere Arbeitsbedingungen können Belastungen mindern und die Bindung von Personal unterstützen. Der direkte Beitrag zu mehr verfügbaren Betreuungsstunden ist begrenzt und nicht gut untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (7317, 17, 'Kita-Platzvergabe bundesweit nach Bedarf priorisieren (Bund)', 'Eine Priorisierung kann Plätze für bestimmte Familien zugänglicher machen, erhöht aber nicht die Zahl der Plätze und kann andere Familien benachteiligen. Ein bundesweiter Eingriff in die Vergabe erfordert Abstimmung mit Ländern und Kommunen.', 'offen', null, 'bund', null, true, 'blind'),
  (7318, 17, 'Verpflichtenden beitragsfreien Kita-Besuch bei Deutschförderbedarf einführen (Bund)', 'Frühe Sprachförderung kann den Förderzugang verbessern, aber eine Pflicht erhöht nicht das knappe Platzangebot. Bedarfsermittlung, Zuständigkeit und Durchsetzung sind anspruchsvoll.', 'gemischt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'bund', null, true, 'blind'),
  (7319, 17, 'Rechtsanspruch auf zehn Stunden Kita-Betreuung täglich schaffen (Land)', 'Ein längerer Anspruch kann den Betreuungsumfang für Familien mit entsprechendem Bedarf direkt verbessern. Er verlangt zusätzliche Plätze und Personal und ist ohne entsprechende Kapazitäten innerhalb einer Wahlperiode schwer erfüllbar.', 'gemischt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'land', null, true, 'blind'),
  (7320, 17, 'Bundeseinheitliche Qualitätsstandards für Kitas festlegen (Bund)', 'Gemeinsame Standards können regionale Mindestqualität und Ausfallberücksichtigung verbessern. Ihre Umsetzung erfordert Abstimmung mit den Ländern und zusätzliche Mittel, wenn sie über bestehende Ausstattung hinausgehen.', 'gemischt', 'https://www.dji.de/themen/kinderbetreuung/plaetze-und-personalschluessel.html', 'bund', null, true, 'blind'),
  (7321, 17, 'Zusatzmittel für Kitas mit Platzmangel oder sozialem Förderbedarf bereitstellen (Bund)', 'Gezielte Mittel können zusätzliche Kapazitäten und Förderung an Orten mit hohem Bedarf unterstützen. Ob Plätze entstehen, hängt von Umsetzung, Personal und ergänzender kommunaler Finanzierung ab.', 'gemischt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'bund', null, true, 'blind'),
  (7322, 17, 'Betreuungsanspruch bis zum 14. Lebensjahr aufrechterhalten (Land)', 'Ein Anspruch für ältere Kinder geht über das für dieses Thema erforderliche Kita-Angebot hinaus und schafft keinen Platz. Umfang, Zuständigkeiten und Finanzierung machen die Umsetzung schwierig.', 'offen', null, 'land', null, true, 'blind'),
  (7323, 17, 'Zusätzliche pädagogische Kita-Leistungen gegen Elternbeiträge ermöglichen (Land)', 'Zusätzliche kostenpflichtige Leistungen verbessern die Bezahlbarkeit der Grundbetreuung nicht und können die Belastung von Familien erhöhen. Die Erlaubnis ist administrativ umsetzbar, wirkt aber dem Kostenziel nicht entgegen.', 'offen', null, 'land', null, true, 'blind'),
  (7324, 17, 'Kinderbetreuung für Hochschulangehörige schaffen (Land)', 'Ein gezieltes Angebot kann den Zugang für Hochschulangehörige verbessern, löst aber nur einen kleinen Teil des allgemeinen Platzmangels. Personal- und Investitionsbedarf bleiben bestehen.', 'offen', null, 'land', null, true, 'blind'),
  (8560, 17, 'Bundesweite Personalschlüssel von 1:3 und 1:7,5 mit Gruppenhöchstgrößen festlegen (Bund)', 'Die Zielwerte entsprechen den fachlichen Empfehlungen und setzen direkt an der Personalausstattung an. Für eine bundesweite Umsetzung fehlen absehbar sehr viele Fachkräfte; Umsetzung durch die Länder und Finanzierung sind ungeklärt.', 'belegt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'bund', null, true, 'blind'),
  (8561, 17, 'Vergütung pädagogischer Fachkräfte an die von Lehrkräften angleichen (Bund)', 'Die meisten Fachkräfte halten ihr Gehalt für unangemessen; höhere Löhne können Berufswahl und Verbleib stärken. Frühere Lohnzuwächse schlossen die Lücke aber nicht; der Bund ist nicht Tarifpartei, die Kosten sind sehr hoch.', 'gemischt', 'https://www.diw.de/de/diw_01.c.817992.de/publikationen/wochenberichte/2021_19_1/erzieherinnen_empfinden_vielfache_belastungen_und_wenig_anerkennung.html', 'bund', null, true, 'blind'),
  (8562, 17, 'Multiprofessionelle Teams zur Entlastung pädagogischer Fachkräfte fördern (Bund)', 'Zusätzliche Kräfte für Sprache, Verwaltung und Unterstützung können Fachkräfte entlasten; Entlastung durch Verwaltungskräfte wird empfohlen. Die Wirkung ist kaum untersucht, Ehrenamtliche ersetzen keine Fachkräfte, der Bund kann nur fördern.', 'offen', 'https://www.bertelsmann-stiftung.de/en/themen/aktuelle-meldungen/2023/november/mehr-plaetze-und-bessere-qualitaet-in-kitas-bis-2030-wenn-jetzt-entschlossen-gehandelt-wird', 'bund', null, true, 'blind'),
  (8563, 17, 'Bundesweite digitale Plattform für Kita-Platzvergabe mit Anzeige freier Plätze (Bund)', 'Zentrale digitale Vergabe beschleunigt das Verfahren, macht es fairer und zeigt den tatsächlichen Bedarf. Sie schafft keine zusätzlichen Plätze; die Vergabe liegt bei Kommunen und Trägern, deren Anbindung der Bund nicht allein regelt.', 'gemischt', 'https://www.bertelsmann-stiftung.de/de/themen/aktuelle-meldungen/2023/juni/schneller-fairer-und-transparenter-zum-kita-platz-wie-ein-algorithmus-kommunen-helfen-kann', 'bund', null, true, 'blind')
on conflict (id) do update set thema_id = excluded.thema_id, name = excluded.name, begruendung = excluded.begruendung,
  evidenz = excluded.evidenz, beleg_studie_url = excluded.beleg_studie_url, ebene = excluded.ebene,
  entspricht = excluded.entspricht, ki_entwurf = excluded.ki_entwurf, entwurf_herkunft = excluded.entwurf_herkunft;

delete from public.instrumente where thema_id = 17 and id not in (7272, 7273, 7274, 7275, 7276, 7277, 7278, 7279, 7280, 7281, 7282, 7283, 7284, 7285, 7286, 7287, 7288, 7289, 7290, 7291, 7292, 7293, 7294, 7295, 7296, 7297, 7298, 7299, 7300, 7301, 7302, 7303, 7304, 7305, 7306, 7307, 7308, 7309, 7310, 7311, 7312, 7313, 7314, 7315, 7316, 7317, 7318, 7319, 7320, 7321, 7322, 7323, 7324, 8560, 8561, 8562, 8563);

insert into public.massnahmen (id, thema_id, partei_id, land, beschreibung, ursachen_ids, instrument_id, wirksamkeit, umsetzbarkeit,
  rollen_modifikator, begruendung, beleg_programm_url, beleg_studie_url, evidenz, stand, geprueft, ki_entwurf, entwurf_herkunft) values
  (7325, 17, 11, null, 'Länder und Kommunen mit einem Investitionsprogramm beim Ausbau von Betreuungsplätzen unterstützen.', '{1701}', 7280, 2, 2, null, 'Investitionshilfen können zusätzliche Plätze und erreichbare Angebote ermöglichen. Die Wirkung hängt von kommunaler Planung, Kofinanzierung und verfügbarem Personal ab.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=65', 'https://www.dji.de/themen/kinderbetreuung/kita-personalbedarf.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7326, 17, 11, null, 'Die steuerliche Absetzbarkeit von Kinderbetreuungskosten verbessern.', '{1705}', 7306, 1, 3, null, 'Steuerliche Abzüge können einen Teil der Kosten kompensieren. Die Entlastung ist geringer oder fehlt bei Familien mit niedriger Steuerlast und löst weder Platzmangel noch hohe laufende Beiträge direkt.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=63', 'https://www.oecd.org/en/publications/education-at-a-glance-2024_c00cad36-en.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7327, 17, 12, null, 'Fachkräfteoffensive für Kitas und Schulen mit mehr Ausbildungskapazitäten und entlohnter Erzieherausbildung vereinbaren; mehr Fachkräfte sollen mehr Plätze und weniger Schließzeiten ermöglichen.', '{1701,1702,1704}', 7295, 2, 2, null, 'Bundesmittel für vergütete Ausbildung, Kapazitäten und Qualifizierung können den Ländern beim Aufbau des Personals helfen. Wirkung und Zeitbedarf hängen von Länderumsetzung und Ausbildungserfolg ab.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=15', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7328, 17, 12, null, 'Kostenfreie Bildung ab der Kita.', '{1705}', 7303, 2, 2, null, 'Geringere Beiträge entlasten Familien und können den Zugang erleichtern, beseitigen aber nicht alle Zusatzkosten. Mehr Nachfrage kann bei knappen Plätzen den Zugang erschweren, wenn der Ausbau nicht Schritt hält.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=26', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7329, 17, 13, null, 'Steuerliche Anreize für Unternehmen, die selbst oder gemeinsam mit anderen Betreuungsplätze schaffen.', '{1701}', 7281, 2, 3, null, 'Anreize können zusätzliche betriebliche Plätze mobilisieren, besonders für Beschäftigte mit passenden Arbeitszeiten. Wie viele zusätzliche Plätze dadurch entstehen, ist für die konkrete Ausgestaltung unsicher.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=76', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7330, 17, 13, null, 'Fachkräfte für Kitas und Kindertagespflege gewinnen und sichern: vergütete, schulgeldfreie Ausbildung, attraktivere Arbeitsplätze, erleichterte Anerkennung und Weiterbildung.', '{1702,1704}', 7295, 2, 2, null, 'Bundesmittel für vergütete Ausbildung, Kapazitäten und Qualifizierung können den Ländern beim Aufbau des Personals helfen. Wirkung und Zeitbedarf hängen von Länderumsetzung und Ausbildungserfolg ab.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=75', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7331, 17, 13, null, 'Einkommensabhängige Kita-Gebühren als Standard einführen.', '{1705}', 7305, 2, 2, null, 'Einkommensabhängige Beiträge können die Belastung gezielter bei Familien mit geringem Einkommen senken. Der Bund kann Vorgaben zur Staffelung machen, Höhe und Erhebung der Beiträge liegen aber bei Ländern und Kommunen; die Angebotsknappheit bleibt.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=76', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true, 'nicht_blind'),
  (7332, 17, 14, null, 'Kindertagespflege als weitere Säule der Kindertagesbetreuung stärken.', '{1701}', 7301, 2, 2, null, 'Bundesunterstützung kann die Länder beim Erhalt und Ausbau ergänzender Betreuungsplätze unterstützen. Die konkrete Wirkung hängt von Umsetzung und dauerhafter Finanzierung vor Ort ab.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=7', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7333, 17, 14, null, 'Startchancen-Programm für Kitas mit akutem Platzmangel oder hohem Anteil sozial benachteiligter Kinder.', '{1701}', 7321, 2, 2, null, 'Gezielte Mittel können zusätzliche Kapazitäten und Förderung an Orten mit hohem Bedarf unterstützen. Ob Plätze entstehen, hängt von Umsetzung, Personal und ergänzender kommunaler Finanzierung ab.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=7', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7334, 17, 14, null, 'Ausbau von Betriebskindergärten unterstützen und bürokratische Hürden abbauen.', '{1701}', 7281, 2, 3, null, 'Anreize können zusätzliche betriebliche Plätze mobilisieren, besonders für Beschäftigte mit passenden Arbeitszeiten. Wie viele zusätzliche Plätze dadurch entstehen, ist für die konkrete Ausgestaltung unsicher.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=31', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7335, 17, 14, null, 'Bundeseinheitliche Kita-Qualitätsstandards mit bedarfsgerechtem Betreuungsschlüssel inklusive Ausfallzeiten, weniger Bürokratie und multiprofessionellen Teams.', '{1702,1703,1704}', 7320, 2, 2, null, 'Gemeinsame Standards können regionale Mindestqualität und Ausfallberücksichtigung verbessern. Ihre Umsetzung erfordert Abstimmung mit den Ländern und zusätzliche Mittel, wenn sie über bestehende Ausstattung hinausgehen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=7', 'https://www.dji.de/themen/kinderbetreuung/plaetze-und-personalschluessel.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7336, 17, 14, null, 'Erzieherausbildung und Weiterbildung schulgeldfrei und vergütet anbieten, Ausbildungskapazitäten der Länder erhöhen.', '{1702}', 7295, 2, 2, null, 'Bundesmittel für vergütete Ausbildung, Kapazitäten und Qualifizierung können den Ländern beim Aufbau des Personals helfen. Wirkung und Zeitbedarf hängen von Länderumsetzung und Ausbildungserfolg ab.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=8', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7337, 17, 14, null, 'Bei Arbeitskämpfen in Kitas verpflichtende Schlichtung, Mindestankündigungsfristen und Notbetrieb vorsehen.', '{1704}', 7312, 1, 2, null, 'Vorankündigung und Schlichtung könnten Familien mehr Planungssicherheit geben. Sie verhindern weder krankheitsbedingte Ausfälle noch lösen sie Personalengpässe; arbeitsrechtliche Ausgestaltung ist anspruchsvoll.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=19', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7338, 17, 14, null, 'Kinderbetreuungskosten über ein Lebenschancen-BAföG mitfinanzieren.', '{1705}', 7308, 1, 2, null, 'Ein zweckgebundener Zuschuss kann einzelne Familien bei den Kosten entlasten. Seine Reichweite hängt von Anspruchshöhe und Zugang ab und beeinflusst das Platzangebot nicht.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=10', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7339, 17, 14, null, 'Steuerlichen Abzug von Kinderbetreuungskosten verbessern.', '{1705}', 7306, 1, 3, null, 'Steuerliche Abzüge können einen Teil der Kosten kompensieren. Die Entlastung ist geringer oder fehlt bei Familien mit niedriger Steuerlast und löst weder Platzmangel noch hohe laufende Beiträge direkt.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=31', 'https://www.oecd.org/en/publications/education-at-a-glance-2024_c00cad36-en.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7340, 17, 15, null, 'Ausreichend Kindergarten- und Kitaplätze in Wohnraumnähe bereitstellen, mit Vorrang für Familien mit zwei arbeitenden Eltern und arbeitende Alleinerziehende.', '{1701}', 7317, 1, 1, null, 'Eine Priorisierung kann Plätze für bestimmte Familien zugänglicher machen, erhöht aber nicht die Zahl der Plätze und kann andere Familien benachteiligen. Ein bundesweiter Eingriff in die Vergabe erfordert Abstimmung mit Ländern und Kommunen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=21', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7341, 17, 15, null, 'Krippen und Kitas ausreichend und qualifiziert besetzen; ein Betreuungsgehalt soll die Nachfrage nach Kitaplätzen und damit den Fachkräftemangel senken.', '{1701,1702}', 7315, 1, 2, null, 'Ein Betreuungsgehalt kann einzelne Familien finanziell entlasten, stellt aber keine bedarfsgerechte externe Betreuung sicher. Ob es die Platznachfrage dauerhaft senkt, ist unklar.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=153', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7342, 17, 15, null, 'Betriebskindergärten stärker fördern.', '{1701}', 7281, 2, 3, null, 'Anreize können zusätzliche betriebliche Plätze mobilisieren, besonders für Beschäftigte mit passenden Arbeitszeiten. Wie viele zusätzliche Plätze dadurch entstehen, ist für die konkrete Ausgestaltung unsicher.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=153', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7343, 17, 16, null, 'Rechtsanspruch auf Ganztagsbetreuung umsetzen und ausreichend Kitaplätze schaffen.', '{1701}', 7280, 2, 2, null, 'Investitionshilfen können zusätzliche Plätze und erreichbare Angebote ermöglichen. Die Wirkung hängt von kommunaler Planung, Kofinanzierung und verfügbarem Personal ab.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=16', 'https://www.dji.de/themen/kinderbetreuung/kita-personalbedarf.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7344, 17, 16, null, 'Familienentlastende Infrastruktur mit guter Erreichbarkeit ausbauen, Kitas in allen Stadtteilen.', '{1701}', 7280, 2, 2, null, 'Investitionshilfen können zusätzliche Plätze und erreichbare Angebote ermöglichen. Die Wirkung hängt von kommunaler Planung, Kofinanzierung und verfügbarem Personal ab.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=45', 'https://www.dji.de/themen/kinderbetreuung/kita-personalbedarf.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7345, 17, 16, null, 'Betreuungsschlüssel auf höchstens eine Fachkraft für drei Kinder unter drei Jahren und 7,5 ältere Kinder verbessern, unter Berücksichtigung von Ausfall- und Vorbereitungszeiten.', '{1702,1703}', 7290, 2, 2, null, 'Einheitliche Mindeststandards können die Qualität und Berücksichtigung von Ausfällen stärken. Die Länder setzen sie um; Personalverfügbarkeit und Finanzierung bestimmen die tatsächliche Wirkung.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=38', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7346, 17, 16, null, 'Löhne in den Sozial- und Erziehungsdiensten erhöhen und Refinanzierung der Tarifverträge sichern.', '{1702}', 7292, 2, 2, null, 'Die Refinanzierung kann Trägern ermöglichen, tarifliche Löhne zu zahlen und Personal zu halten. Der Bund kann Kosten mittragen, aber die tatsächliche Personalgewinnung ist nicht garantiert.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=38', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7347, 17, 16, null, 'Zugang zur Erzieher*innen-Ausbildung erleichtern und Ausbildungsqualität erhöhen.', '{1702}', 7295, 2, 2, null, 'Bundesmittel für vergütete Ausbildung, Kapazitäten und Qualifizierung können den Ländern beim Aufbau des Personals helfen. Wirkung und Zeitbedarf hängen von Länderumsetzung und Ausbildungserfolg ab.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=38', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7348, 17, 16, null, 'Kitas für alle Kinder gebührenfrei machen.', '{1705}', 7303, 2, 2, null, 'Geringere Beiträge entlasten Familien und können den Zugang erleichtern, beseitigen aber nicht alle Zusatzkosten. Mehr Nachfrage kann bei knappen Plätzen den Zugang erschweren, wenn der Ausbau nicht Schritt hält.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=38', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7349, 17, 17, null, 'Unternehmen stärker zur Bereitstellung von Kita-Plätzen verpflichten, im Gegenzug steuerliche Vorteile.', '{1701}', 7281, 2, 3, null, 'Anreize können zusätzliche betriebliche Plätze mobilisieren, besonders für Beschäftigte mit passenden Arbeitszeiten. Wie viele zusätzliche Plätze dadurch entstehen, ist für die konkrete Ausgestaltung unsicher.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=32', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7350, 17, 17, null, 'Länder und Kommunen bei der Ausbildung von mehr Erziehern unterstützen, Arbeitsbedingungen in Bildungseinrichtungen verbessern.', '{1702}', 7295, 2, 2, null, 'Bundesmittel für vergütete Ausbildung, Kapazitäten und Qualifizierung können den Ländern beim Aufbau des Personals helfen. Wirkung und Zeitbedarf hängen von Länderumsetzung und Ausbildungserfolg ab.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=25', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7351, 17, 17, null, 'Für Kinder ab drei Jahren mit festgestellten Deutschdefiziten verpflichtender, beitragsfreier Kita-Besuch mit Sprachbildung.', '{1705}', 7318, 1, 1, null, 'Frühe Sprachförderung kann den Förderzugang verbessern, aber eine Pflicht erhöht nicht das knappe Platzangebot. Bedarfsermittlung, Zuständigkeit und Durchsetzung sind anspruchsvoll.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=24', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7352, 17, 17, null, 'Kita-Beiträge stabilisieren oder senken, mittelfristig Beitragsfreiheit.', '{1705}', 7303, 2, 2, null, 'Geringere Beiträge entlasten Familien und können den Zugang erleichtern, beseitigen aber nicht alle Zusatzkosten. Mehr Nachfrage kann bei knappen Plätzen den Zugang erschweren, wenn der Ausbau nicht Schritt hält.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=24', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7353, 17, 11, 'ST', 'Konzept vorlegen, das den Bedarf erfasst, die Finanzierung stabilisiert und den Personalschlüssel verbessert.', '{1701,1702,1703,1704}', 7276, 2, 3, null, 'Kleinräumige Planung kann Plätze besser an Bedarf und Bevölkerungsentwicklung anpassen. Sie behebt einen landesweiten Personal- oder Finanzmangel nicht allein.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=49', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7354, 17, 11, 'ST', 'Wohnortnahe Betreuung erhalten und über flexible Modelle, Kooperationen und Zusammenschlüsse an die regionale Nachfrage anpassen.', '{1701}', 7276, 2, 3, null, 'Kleinräumige Planung kann Plätze besser an Bedarf und Bevölkerungsentwicklung anpassen. Sie behebt einen landesweiten Personal- oder Finanzmangel nicht allein.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=49', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7355, 17, 11, 'ST', 'Dokumentationspflichten abbauen, Arbeitsalltag digital unterstützen, Leitungskräfte entlasten.', '{1702}', 7296, 1, 3, null, 'Weniger unnötige Dokumentation kann Fachkräfte und Leitung entlasten. Freigesetzte Zeit ersetzt keine zusätzlichen Betreuungskräfte und hängt von einer sorgfältigen Auswahl der Pflichten ab.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=49', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7356, 17, 11, 'ST', 'Kindertagespflege durch faire Vergütung, Beratung und Sachkostenförderung stärken.', '{1701,1702}', 7299, 2, 2, null, 'Faire Entgelte, Beratung und klare Vereinbarungen können Tagespflegepersonen halten und zusätzliche Plätze ermöglichen. Die Zahl der erreichbaren Plätze bleibt von der Gewinnung und Bindung der Betreuungspersonen abhängig.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=49', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7357, 17, 11, 'ST', 'Kitas bedarfsgerecht ausbauen und sanieren, flexible Öffnungszeitenmodelle fördern.', '{1701}', 7274, 2, 2, null, 'Zusätzliche und gesicherte Plätze wirken unmittelbar gegen Angebotslücken; der tatsächliche Effekt hängt von Personalverfügbarkeit und regionaler Planung ab. Investitionen und laufende Kosten begrenzen das Tempo.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=50', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7358, 17, 12, 'ST', 'Zusätzliche Personalmittel über „Kita STABIL“ bereitstellen und das Programm über 2028 hinaus fortsetzen.', '{1701,1702}', 7313, 2, 2, null, 'Zusätzliche Personalressourcen können Ausfälle auffangen und Betreuung stabilisieren. Eine dauerhafte Wirkung setzt verlässliche Finanzierung und verfügbare Fachkräfte voraus.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=27', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7359, 17, 12, 'ST', 'Flexible Öffnungszeiten von Kitas bis in Randzeiten ausbauen.', '{1701}', 7277, 2, 2, null, 'Bedarfsgerechte Zeiten und Ersatzangebote können Versorgungslücken für Familien mit besonderen Arbeitszeiten abfedern. Personalbedarf, Nachfrage und Qualität begrenzen die flächendeckende Umsetzung.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=28', 'https://www.dji.de/themen/kinderbetreuung/eltern-wuenschen-sich-flexiblere-betreuungsangebote.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7360, 17, 12, 'ST', 'Rechtsanspruch auf bis zu zehn Stunden Betreuung von Geburt bis zum 14. Lebensjahr aufrechterhalten.', '{1701}', 7322, 1, 1, null, 'Ein Anspruch für ältere Kinder geht über das für dieses Thema erforderliche Kita-Angebot hinaus und schafft keinen Platz. Umfang, Zuständigkeiten und Finanzierung machen die Umsetzung schwierig.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=27', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7361, 17, 12, 'ST', 'Tatsächlichen Personalschlüssel in Kitas schrittweise verbessern.', '{1703}', 7287, 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=28', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7362, 17, 12, 'ST', 'Kitas mit besonderen sozialen Herausforderungen zusätzlich unterstützen.', '{1702}', 7298, 2, 2, null, 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=28', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7363, 17, 12, 'ST', 'Kurzfristige Entlastung von Eltern mit mehreren Kindern bei den Betreuungskosten sichern.', '{1705}', 7304, 1, 3, null, 'Ermäßigungen mindern die finanzielle Belastung größerer Familien, ohne die Kosten für alle Eltern abzuschaffen. Die Entlastung erreicht nur Familien, die die jeweilige Regelung nutzen.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=28', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7364, 17, 13, 'ST', 'Nachhaltige kommunale Kitaplanung finanzieren.', '{1701}', 7276, 2, 3, null, 'Kleinräumige Planung kann Plätze besser an Bedarf und Bevölkerungsentwicklung anpassen. Sie behebt einen landesweiten Personal- oder Finanzmangel nicht allein.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=57', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7365, 17, 13, 'ST', 'Programm „HeimatKita“: wohnortnahe Betreuung zusichern und Kleinst-Kitas unterstützen.', '{1701}', 7274, 2, 2, null, 'Zusätzliche und gesicherte Plätze wirken unmittelbar gegen Angebotslücken; der tatsächliche Effekt hängt von Personalverfügbarkeit und regionaler Planung ab. Investitionen und laufende Kosten begrenzen das Tempo.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=57', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7366, 17, 13, 'ST', 'Befristete Personalsicherung durch „Kita STABIL“ in eine langfristige strukturelle Verbesserung überführen.', '{1702}', 7313, 2, 2, null, 'Zusätzliche Personalressourcen können Ausfälle auffangen und Betreuung stabilisieren. Eine dauerhafte Wirkung setzt verlässliche Finanzierung und verfügbare Fachkräfte voraus.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=57', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7367, 17, 13, 'ST', 'Mindestpersonalschlüssel anheben, Sonderförderung für Kitas mit besonderen Bedarfen und Kita-Sozialarbeit ausbauen.', '{1702,1703}', 7298, 2, 2, null, 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=57', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7368, 17, 13, 'ST', 'Bezahlung und Arbeitsbedingungen für Erzieher*innen verbessern, von Bürokratie entlasten.', '{1702}', 7291, 2, 2, null, 'Bessere Bezahlung und Arbeitsbedingungen können die Attraktivität und Bindung von Fachkräften erhöhen. Der Fachkräftemangel und die Tarif- und Haushaltskosten begrenzen Geschwindigkeit und Reichweite.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=57', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7369, 17, 13, 'ST', 'Erzieher*innen im Anerkennungsjahr unabhängig von der Trägerschaft angemessen vergüten.', '{1702}', 7294, 2, 2, null, 'Vergütung kann den Zugang zur Ausbildung erleichtern und die Zahl der Auszubildenden erhöhen. Ein unmittelbarer Effekt auf verfügbare Fachkräfte entsteht erst nach Ausbildungsabschluss.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=57', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7370, 17, 13, 'ST', 'Beitragsermäßigung für Mehrkinderfamilien dauerhaft sichern, Modell zur sozialen Staffelung der Kitabeiträge erarbeiten.', '{1705}', 7304, 1, 3, null, 'Ermäßigungen mindern die finanzielle Belastung größerer Familien, ohne die Kosten für alle Eltern abzuschaffen. Die Entlastung erreicht nur Familien, die die jeweilige Regelung nutzen.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=57', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7371, 17, 14, 'ST', 'Flexible Öffnungszeiten am tatsächlichen Bedarf der Familien ausrichten.', '{1701}', 7277, 2, 2, null, 'Bedarfsgerechte Zeiten und Ersatzangebote können Versorgungslücken für Familien mit besonderen Arbeitszeiten abfedern. Personalbedarf, Nachfrage und Qualität begrenzen die flächendeckende Umsetzung.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=23', 'https://www.dji.de/themen/kinderbetreuung/eltern-wuenschen-sich-flexiblere-betreuungsangebote.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7372, 17, 14, 'ST', 'Landesmodellprojekt für Gemeinschaftsbüros mit Kinderbetreuung und mobile Betreuungsreserven.', '{1701,1704}', 7277, 2, 2, null, 'Bedarfsgerechte Zeiten und Ersatzangebote können Versorgungslücken für Familien mit besonderen Arbeitszeiten abfedern. Personalbedarf, Nachfrage und Qualität begrenzen die flächendeckende Umsetzung.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=24', 'https://www.dji.de/themen/kinderbetreuung/eltern-wuenschen-sich-flexiblere-betreuungsangebote.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7373, 17, 14, 'ST', 'Kurzfristig einspringende Betreuungszusammenschlüsse für Zeiten außerhalb der üblichen Öffnungszeiten unterstützen.', '{1701,1704}', 7277, 2, 2, null, 'Bedarfsgerechte Zeiten und Ersatzangebote können Versorgungslücken für Familien mit besonderen Arbeitszeiten abfedern. Personalbedarf, Nachfrage und Qualität begrenzen die flächendeckende Umsetzung.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=24', 'https://www.dji.de/themen/kinderbetreuung/eltern-wuenschen-sich-flexiblere-betreuungsangebote.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7374, 17, 14, 'ST', 'Erzieherinnen und Erzieher entsprechend ausbilden und von Dokumentationspflichten entlasten.', '{1702}', 7293, 2, 2, null, 'Mehr Ausbildungsplätze, Praxisanteile und Quereinstiege können mittelfristig den Personalzugang verbessern. Fehlende Lehrkräfte, Räume und Ausbildungserfolg begrenzen den Zuwachs.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=24', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7375, 17, 14, 'ST', 'Betreuungsschlüssel an den Förderbedarf anpassen und unterstützendes Personal einsetzen.', '{1702,1703}', 7298, 2, 2, null, 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=25', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7376, 17, 14, 'ST', 'Geschwisterkindregelung bei den Elternbeiträgen ändern, ohne sie abzuschaffen.', '{1705}', 7304, 1, 3, null, 'Ermäßigungen mindern die finanzielle Belastung größerer Familien, ohne die Kosten für alle Eltern abzuschaffen. Die Entlastung erreicht nur Familien, die die jeweilige Regelung nutzen.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=25', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7377, 17, 15, 'ST', 'Krippen und Kindergärten ab dem ersten Kind mit dauerhaft gesicherter Landesfinanzierung kostenfrei machen.', '{1705}', 7302, 2, 2, null, 'Beitragsfreiheit entlastet Familien und kann die Nutzung besonders bei jüngeren Kindern erhöhen. Sie schafft zusätzliche Nachfrage und kann Mittel binden, die sonst für Qualität oder Plätze verfügbar wären.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=18', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7378, 17, 16, 'ST', 'Uneingeschränkten Rechtsanspruch auf zehn Stunden Betreuung täglich in Kindertageseinrichtungen schaffen.', '{1701}', 7319, 2, 1, null, 'Ein längerer Anspruch kann den Betreuungsumfang für Familien mit entsprechendem Bedarf direkt verbessern. Er verlangt zusätzliche Plätze und Personal und ist ohne entsprechende Kapazitäten innerhalb einer Wahlperiode schwer erfüllbar.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=29', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7379, 17, 16, 'ST', 'Multiprofessionelle Teams in Kitas flächendeckend aufbauen und die nötigen personellen und finanziellen Ressourcen sichern.', '{1702}', 7298, 2, 2, null, 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=27', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7380, 17, 16, 'ST', 'Personalschlüssel auf 1:3 in Krippen und 1:7,5 in Kindergärten verbessern.', '{1702,1703}', 7286, 3, 2, null, 'Die konkreten Zielwerte setzen direkt an der Personalausstattung an, die pädagogische Interaktionen ermöglicht. Die Verbesserung ist wirksam, erfordert angesichts des Fachkräftemangels aber zusätzliche Personal- und Finanzressourcen.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=29', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7381, 17, 16, 'ST', 'Für die Kindertagespflege Leistungs-, Entgelt- und Qualitätsvereinbarungen mit den Jugendämtern abschließen.', '{1702}', 7299, 2, 2, null, 'Faire Entgelte, Beratung und klare Vereinbarungen können Tagespflegepersonen halten und zusätzliche Plätze ermöglichen. Die Zahl der erreichbaren Plätze bleibt von der Gewinnung und Bindung der Betreuungspersonen abhängig.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=29', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7382, 17, 16, 'ST', 'Bildung in Kindertageseinrichtungen für alle Eltern beitragsfrei machen.', '{1705}', 7302, 2, 2, null, 'Beitragsfreiheit entlastet Familien und kann die Nutzung besonders bei jüngeren Kindern erhöhen. Sie schafft zusätzliche Nachfrage und kann Mittel binden, die sonst für Qualität oder Plätze verfügbar wären.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=29', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7383, 17, 16, 'ST', 'Kostenlose Mittagsversorgung für Kinder in Kitas und Kindertagespflege.', '{1705}', 7310, 1, 2, null, 'Kostenfreie Mahlzeiten senken einen Teil der Familienausgaben, lassen Elternbeiträge und weitere Zusatzkosten aber bestehen. Die Wirkung auf die Gesamtbelastung ist daher begrenzt.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=29', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7384, 17, 16, 'ST', 'Finanzierung an den tatsächlichen Personalkosten ausrichten; Elternbeiträge und Mehrkosten besserer Personalschlüssel vollständig vom Land finanzieren.', '{1702,1703,1705}', 7307, 2, 2, null, 'Eine Finanzierung der tatsächlichen Kosten kann bessere Personalausstattung ermöglichen und Beitragsbelastungen begrenzen. Die Ausgabenhöhe und die Verteilung zwischen Land, Kommunen und Trägern sind anspruchsvoll.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=29', 'https://www.dji.de/themen/kinderbetreuung/plaetze-und-personalschluessel.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7385, 17, 16, 'ST', 'Alle Kita-Standorte im Land erhalten.', '{1701}', 7274, 2, 2, null, 'Zusätzliche und gesicherte Plätze wirken unmittelbar gegen Angebotslücken; der tatsächliche Effekt hängt von Personalverfügbarkeit und regionaler Planung ab. Investitionen und laufende Kosten begrenzen das Tempo.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=46', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7386, 17, 17, 'ST', 'Ausbildungskapazitäten für Erzieher ausweiten und Studienplätze in der Kindheitspädagogik ausbauen.', '{1702}', 7293, 2, 2, null, 'Mehr Ausbildungsplätze, Praxisanteile und Quereinstiege können mittelfristig den Personalzugang verbessern. Fehlende Lehrkräfte, Räume und Ausbildungserfolg begrenzen den Zuwachs.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=46', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7387, 17, 17, 'ST', 'Ausbildungs- und Arbeitsbedingungen im frühkindlichen Bereich durch Bezahlung, verlässliche Arbeitszeiten und Ausbildungsvergütung aufwerten.', '{1702}', 7291, 2, 2, null, 'Bessere Bezahlung und Arbeitsbedingungen können die Attraktivität und Bindung von Fachkräften erhöhen. Der Fachkräftemangel und die Tarif- und Haushaltskosten begrenzen Geschwindigkeit und Reichweite.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=46', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7388, 17, 17, 'ST', 'Personal-Kind-Betreuungsschlüssel stärken.', '{1703}', 7287, 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=46', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7389, 17, 17, 'ST', 'Beitragsfreie Kitas einführen.', '{1705}', 7302, 2, 2, null, 'Beitragsfreiheit entlastet Familien und kann die Nutzung besonders bei jüngeren Kindern erhöhen. Sie schafft zusätzliche Nachfrage und kann Mittel binden, die sonst für Qualität oder Plätze verfügbar wären.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=46', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7390, 17, 11, 'MV', 'Planungs- und Genehmigungsverfahren für Kitas beschleunigen.', '{1701}', 7273, 2, 3, null, 'Kürzere Verfahren können den Ausbau erleichtern, schaffen aber weder Bauflächen noch Personal. Verwaltungsvereinfachungen sind innerhalb einer Wahlperiode realistisch.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=42', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7391, 17, 11, 'MV', 'Kindertagesbetreuung für Hochschulangehörige schaffen.', '{1701}', 7324, 1, 2, null, 'Ein gezieltes Angebot kann den Zugang für Hochschulangehörige verbessern, löst aber nur einen kleinen Teil des allgemeinen Platzmangels. Personal- und Investitionsbedarf bleiben bestehen.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=68', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7392, 17, 11, 'MV', 'Freiwerdende Ressourcen für bessere Betreuungsschlüssel einsetzen.', '{1703}', 7287, 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=45', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7393, 17, 11, 'MV', 'Mit relevanten Akteuren einen Perspektivplan zur Verbesserung der Erzieher-Kind-Relation entwickeln.', '{1703}', 7287, 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=45', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7394, 17, 11, 'MV', 'Multiprofessionelle Teams mit spezialisierten Fachkräften in Kindergärten vorschreiben.', '{1702}', 7298, 2, 2, null, 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=45', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7395, 17, 11, 'MV', 'Mittel aus dem Kita-Qualitätsgesetz in qualitätssteigernde Maßnahmen, insbesondere pädagogische Leitungszeit, investieren.', '{1702}', 7314, 2, 2, null, 'Zusätzliche pädagogische Leitungs- und Personalzeit kann die Arbeit in Einrichtungen verbessern. Die Wirkung hängt davon ab, dass Mittel zusätzlich und dauerhaft für qualifiziertes Personal eingesetzt werden.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=45', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7396, 17, 11, 'MV', 'Pädagogische Teams durch Hauswirtschafts- und Verwaltungskräfte entlasten.', '{1702}', 7297, 2, 2, null, 'Zusätzliche Unterstützung kann pädagogischen Fachkräften mehr Zeit für Kinder geben. Sie benötigt weiteres Personal und verbessert nicht automatisch die Fachkraft-Kind-Relation.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=45', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7397, 17, 12, 'MV', 'Runde Tische mit den Kommunen je Landkreis und kreisfreier Stadt für verlässliche Bedarfsplanung einrichten.', '{1701}', 7276, 2, 3, null, 'Kleinräumige Planung kann Plätze besser an Bedarf und Bevölkerungsentwicklung anpassen. Sie behebt einen landesweiten Personal- oder Finanzmangel nicht allein.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=4', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7398, 17, 12, 'MV', 'Gruppengröße in Krippen ab 2027 auf fünf, im Kindergarten ab 2028 auf 13 Kinder je Fachkraft senken.', '{1703}', 7289, 2, 2, null, 'Die festen Stufen verbessern die Personalausstattung, bleiben aber deutlich hinter den fachlichen Empfehlungen von 1:3 und 1:7,5 zurück. Der Zeitplan ist bestimmt, das zusätzliche Personal muss bei Fachkräftemangel aber erst gewonnen werden.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=4', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true, 'nicht_blind'),
  (7399, 17, 12, 'MV', 'Multiprofessionelle Teams schrittweise als Grundausstattung an Kitas einführen, beginnend bei Kitas mit besonderen Herausforderungen.', '{1702}', 7298, 2, 2, null, 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=67', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7400, 17, 12, 'MV', 'Beitragsfreiheit der Kitas fortführen.', '{1705}', 7302, 2, 2, null, 'Beitragsfreiheit entlastet Familien und kann die Nutzung besonders bei jüngeren Kindern erhöhen. Sie schafft zusätzliche Nachfrage und kann Mittel binden, die sonst für Qualität oder Plätze verfügbar wären.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=64', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7401, 17, 13, 'MV', 'Anspruch auf einen vollen Ganztagsplatz für alle Kinder einführen.', '{1701}', 7272, 2, 2, null, 'Ein erfüllter Anspruch verbessert den Zugang direkt, setzt aber ausreichende Plätze und Personal voraus. Die Umsetzung hängt deshalb von regionaler Kapazität und Finanzierung ab.', 'https://gruene-mv.de/?wpdmdl=33772#page=41', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7402, 17, 13, 'MV', 'Landesweites Modellprojekt mit flexibler Kinderbetreuung für junge Eltern.', '{1701}', 7277, 2, 2, null, 'Bedarfsgerechte Zeiten und Ersatzangebote können Versorgungslücken für Familien mit besonderen Arbeitszeiten abfedern. Personalbedarf, Nachfrage und Qualität begrenzen die flächendeckende Umsetzung.', 'https://gruene-mv.de/?wpdmdl=33772#page=84', 'https://www.dji.de/themen/kinderbetreuung/eltern-wuenschen-sich-flexiblere-betreuungsangebote.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7403, 17, 13, 'MV', 'Betreuungsschlüssel deutlich verbessern und sinkende Geburtenzahlen für kleinere Gruppen statt Personalabbau nutzen.', '{1702,1703}', 7287, 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://gruene-mv.de/?wpdmdl=33772#page=41', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7404, 17, 13, 'MV', 'Kindertagespflegepersonen, die Fachstandards erfüllen, entsprechend bezahlen.', '{1702}', 7299, 2, 2, null, 'Faire Entgelte, Beratung und klare Vereinbarungen können Tagespflegepersonen halten und zusätzliche Plätze ermöglichen. Die Zahl der erreichbaren Plätze bleibt von der Gewinnung und Bindung der Betreuungspersonen abhängig.', 'https://gruene-mv.de/?wpdmdl=33772#page=41', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7405, 17, 13, 'MV', 'Beitragsfreie Kita beibehalten.', '{1705}', 7302, 2, 2, null, 'Beitragsfreiheit entlastet Familien und kann die Nutzung besonders bei jüngeren Kindern erhöhen. Sie schafft zusätzliche Nachfrage und kann Mittel binden, die sonst für Qualität oder Plätze verfügbar wären.', 'https://gruene-mv.de/?wpdmdl=33772#page=41', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7406, 17, 14, 'MV', 'Bestehenden Betreuungsanspruch überall verlässlich erfüllen und passgenaue Angebote sichern.', '{1701,1704}', 7272, 2, 2, null, 'Ein erfüllter Anspruch verbessert den Zugang direkt, setzt aber ausreichende Plätze und Personal voraus. Die Umsetzung hängt deshalb von regionaler Kapazität und Finanzierung ab.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=82', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7407, 17, 14, 'MV', 'Landesfinanzierung für Kita und Kindertagespflege an den tatsächlichen Bedarf anpassen.', '{1701}', 7275, 2, 2, null, 'Eine verlässliche Finanzierung kann Plätze erhalten und Ausbau ermöglichen. Der Effekt hängt davon ab, ob Mittel zusätzlich bereitgestellt und tatsächlich für Kapazitäten eingesetzt werden.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=37', 'https://www.dji.de/themen/kinderbetreuung/kita-personalbedarf.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7408, 17, 14, 'MV', 'Private Träger und Betriebskindergärten bei Einhaltung der Qualitätsstandards öffentlich fördern.', '{1701}', 7275, 2, 2, null, 'Eine verlässliche Finanzierung kann Plätze erhalten und Ausbau ermöglichen. Der Effekt hängt davon ab, ob Mittel zusätzlich bereitgestellt und tatsächlich für Kapazitäten eingesetzt werden.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=83', 'https://www.dji.de/themen/kinderbetreuung/kita-personalbedarf.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7409, 17, 14, 'MV', 'Kindertagespflege rechtssicher stärken, Bürokratie abbauen, verlässliche Rahmenbedingungen schaffen.', '{1701}', 7299, 2, 2, null, 'Faire Entgelte, Beratung und klare Vereinbarungen können Tagespflegepersonen halten und zusätzliche Plätze ermöglichen. Die Zahl der erreichbaren Plätze bleibt von der Gewinnung und Bindung der Betreuungspersonen abhängig.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=83', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7410, 17, 14, 'MV', 'Tageseltern angemessen vergüten und Betreuung über das dritte Lebensjahr hinaus ermöglichen.', '{1701}', 7299, 2, 2, null, 'Faire Entgelte, Beratung und klare Vereinbarungen können Tagespflegepersonen halten und zusätzliche Plätze ermöglichen. Die Zahl der erreichbaren Plätze bleibt von der Gewinnung und Bindung der Betreuungspersonen abhängig.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=83', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7411, 17, 14, 'MV', 'Fachkraft-Kind-Relation stufenweise, evidenzbasiert und gegenfinanziert verbessern.', '{1703}', 7287, 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=82', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7412, 17, 14, 'MV', 'Zusätzliche Mittel vorrangig in Personal, Sprachförderung und Verlässlichkeit investieren.', '{1702,1704}', 7314, 2, 2, null, 'Zusätzliche pädagogische Leitungs- und Personalzeit kann die Arbeit in Einrichtungen verbessern. Die Wirkung hängt davon ab, dass Mittel zusätzlich und dauerhaft für qualifiziertes Personal eingesetzt werden.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=82', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7413, 17, 14, 'MV', 'Mehr Fachkräfte durch niedrigere Ausbildungshürden, stärkere Praxisanteile und bedarfsgerechte Ausbildungskapazitäten gewinnen.', '{1702,1703}', 7293, 2, 2, null, 'Mehr Ausbildungsplätze, Praxisanteile und Quereinstiege können mittelfristig den Personalzugang verbessern. Fehlende Lehrkräfte, Räume und Ausbildungserfolg begrenzen den Zuwachs.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=82', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7414, 17, 14, 'MV', 'Erzieherausbildung dual weiterentwickeln, weitere pädagogische und therapeutische Fachkräfte flexibler in Kitas einsetzen.', '{1702}', 7293, 2, 2, null, 'Mehr Ausbildungsplätze, Praxisanteile und Quereinstiege können mittelfristig den Personalzugang verbessern. Fehlende Lehrkräfte, Räume und Ausbildungserfolg begrenzen den Zuwachs.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=82', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7415, 17, 14, 'MV', 'Beschäftigte von Kindertageseinrichtungen bei gleicher Qualifikation und Leistung gleich bezahlen.', '{1702}', 7291, 2, 2, null, 'Bessere Bezahlung und Arbeitsbedingungen können die Attraktivität und Bindung von Fachkräften erhöhen. Der Fachkräftemangel und die Tarif- und Haushaltskosten begrenzen Geschwindigkeit und Reichweite.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=83', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7416, 17, 14, 'MV', 'Kita-Leitungen durch bessere Arbeitsbedingungen, weniger Berichtspflichten, digitale Verwaltung und klare Zuständigkeiten stärken.', '{1702}', 7296, 1, 3, null, 'Weniger unnötige Dokumentation kann Fachkräfte und Leitung entlasten. Freigesetzte Zeit ersetzt keine zusätzlichen Betreuungskräfte und hängt von einer sorgfältigen Auswahl der Pflichten ab.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=83', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7417, 17, 15, 'MV', 'Betreuungsschlüssel in Krippen auf 1:4 und in Kindergärten auf 1:10 verbessern.', '{1702,1703}', 7288, 2, 2, null, 'Die Zielwerte verbessern die Personalausstattung gegenüber ungünstigen Ausgangslagen, bleiben aber hinter den fachlichen Empfehlungen zurück. Zusätzliches Personal ist nötig.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=20', 'https://www.dji.de/themen/kinderbetreuung/plaetze-und-personalschluessel.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7418, 17, 15, 'MV', 'Erzieher angelehnt an den TVöD vergüten und von Dokumentationspflichten entlasten.', '{1702}', 7291, 2, 2, null, 'Bessere Bezahlung und Arbeitsbedingungen können die Attraktivität und Bindung von Fachkräften erhöhen. Der Fachkräftemangel und die Tarif- und Haushaltskosten begrenzen Geschwindigkeit und Reichweite.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=20', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7419, 17, 15, 'MV', 'Beitragsfreie Kitas erhalten.', '{1705}', 7302, 2, 2, null, 'Beitragsfreiheit entlastet Familien und kann die Nutzung besonders bei jüngeren Kindern erhöhen. Sie schafft zusätzliche Nachfrage und kann Mittel binden, die sonst für Qualität oder Plätze verfügbar wären.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=19', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7420, 17, 15, 'MV', 'Kindertagespflegepersonen stärker unterstützen.', '{1701}', 7299, 2, 2, null, 'Faire Entgelte, Beratung und klare Vereinbarungen können Tagespflegepersonen halten und zusätzliche Plätze ermöglichen. Die Zahl der erreichbaren Plätze bleibt von der Gewinnung und Bindung der Betreuungspersonen abhängig.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=20', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7421, 17, 16, 'MV', 'Beitragsfreiheit in Kitas erhalten.', '{1705}', 7302, 2, 2, null, 'Beitragsfreiheit entlastet Familien und kann die Nutzung besonders bei jüngeren Kindern erhöhen. Sie schafft zusätzliche Nachfrage und kann Mittel binden, die sonst für Qualität oder Plätze verfügbar wären.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=5', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7422, 17, 16, 'MV', 'Garantie für eine wohnortnahe Tagesbetreuung für jedes Kind.', '{1701}', 7272, 2, 2, null, 'Ein erfüllter Anspruch verbessert den Zugang direkt, setzt aber ausreichende Plätze und Personal voraus. Die Umsetzung hängt deshalb von regionaler Kapazität und Finanzierung ab.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=5', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7423, 17, 16, 'MV', 'Gruppengröße in der Krippe schrittweise auf vier Kinder je Gruppe senken.', '{1703}', 7288, 2, 2, null, 'Die Zielwerte verbessern die Personalausstattung gegenüber ungünstigen Ausgangslagen, bleiben aber hinter den fachlichen Empfehlungen zurück. Zusätzliches Personal ist nötig.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=5', 'https://www.dji.de/themen/kinderbetreuung/plaetze-und-personalschluessel.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7424, 17, 16, 'MV', 'Arbeitszeiten in Kitas und Kindertagespflege an Arbeitswege und -zeiten der Eltern anpassen.', '{1701}', 7277, 2, 2, null, 'Bedarfsgerechte Zeiten und Ersatzangebote können Versorgungslücken für Familien mit besonderen Arbeitszeiten abfedern. Personalbedarf, Nachfrage und Qualität begrenzen die flächendeckende Umsetzung.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=15', 'https://www.dji.de/themen/kinderbetreuung/eltern-wuenschen-sich-flexiblere-betreuungsangebote.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7425, 17, 17, 'MV', 'Erzieherberuf tariflich aufwerten, Arbeitsbedingungen verbessern und verlässliche Personalausstattung sichern.', '{1702}', 7291, 2, 2, null, 'Bessere Bezahlung und Arbeitsbedingungen können die Attraktivität und Bindung von Fachkräften erhöhen. Der Fachkräftemangel und die Tarif- und Haushaltskosten begrenzen Geschwindigkeit und Reichweite.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=45', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7426, 17, 17, 'MV', 'Betreuungsschlüssel verbessern, damit mehr Zeit für individuelle Förderung bleibt.', '{1703}', 7287, 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=45', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7427, 17, 17, 'MV', 'Beitragsfreie Kita sichern und Kostenbeteiligung des Landes erhöhen.', '{1705}', 7302, 2, 2, null, 'Beitragsfreiheit entlastet Familien und kann die Nutzung besonders bei jüngeren Kindern erhöhen. Sie schafft zusätzliche Nachfrage und kann Mittel binden, die sonst für Qualität oder Plätze verfügbar wären.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=45', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7428, 17, 11, 'BE', 'Flexiblere und längere Betreuungsangebote ausbauen, etwa Betriebskindergärten und zusätzliche Tagesmütter und -väter.', '{1701}', 7277, 2, 2, null, 'Bedarfsgerechte Zeiten und Ersatzangebote können Versorgungslücken für Familien mit besonderen Arbeitszeiten abfedern. Personalbedarf, Nachfrage und Qualität begrenzen die flächendeckende Umsetzung.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=108', 'https://www.dji.de/themen/kinderbetreuung/eltern-wuenschen-sich-flexiblere-betreuungsangebote.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7429, 17, 11, 'BE', 'Kita-Qualitätsoffensive mit Schwerpunkt Sprachbildung und Qualifizierung des pädagogischen Personals.', '{1702}', 7298, 2, 2, null, 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=108', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7430, 17, 11, 'BE', 'Multiprofessionelle Strukturen und Kita-Sozialarbeit stärken.', '{1702}', 7298, 2, 2, null, 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=108', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7431, 17, 11, 'BE', '24-Stunden-Kitas mit Betreuung zu Rand- und Nachtzeiten ausbauen.', '{1701}', 7278, 1, 1, null, 'Nachtbetreuung hilft nur Familien mit entsprechendem Bedarf und löst die allgemeine Angebotslücke kaum. Der hohe Personal- und Organisationsaufwand erschwert eine Umsetzung in der Wahlperiode.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=108', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7432, 17, 11, 'BE', 'Flexible, kostenfreie Betreuungsangebote, insbesondere zu Randzeiten.', '{1705}', 7277, 2, 2, null, 'Bedarfsgerechte Zeiten und Ersatzangebote können Versorgungslücken für Familien mit besonderen Arbeitszeiten abfedern. Personalbedarf, Nachfrage und Qualität begrenzen die flächendeckende Umsetzung.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=108', 'https://www.dji.de/themen/kinderbetreuung/eltern-wuenschen-sich-flexiblere-betreuungsangebote.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7433, 17, 12, 'BE', 'Sanierung und Neubau von Kitas in den Kiezen als Investitionsschwerpunkt des Sondervermögens.', '{1701}', 7274, 2, 2, null, 'Zusätzliche und gesicherte Plätze wirken unmittelbar gegen Angebotslücken; der tatsächliche Effekt hängt von Personalverfügbarkeit und regionaler Planung ab. Investitionen und laufende Kosten begrenzen das Tempo.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=7', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7434, 17, 12, 'BE', 'Finanzierung landeseigener Kita-Betriebe mit Investitionsmitteln stabilisieren, wohnortnahes Angebot in allen Bezirken.', '{1701}', 7274, 2, 2, null, 'Zusätzliche und gesicherte Plätze wirken unmittelbar gegen Angebotslücken; der tatsächliche Effekt hängt von Personalverfügbarkeit und regionaler Planung ab. Investitionen und laufende Kosten begrenzen das Tempo.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=37', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7435, 17, 12, 'BE', 'Betreuungsschlüssel weiter verbessern und mittelbare pädagogische Arbeit durch mehr Personalzeit stärken.', '{1703}', 7287, 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=37', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7436, 17, 12, 'BE', 'Personalschlüssel nur nach tatsächlich anwesendem Personal berechnen; Urlaub, Krankheit und Fortbildung zählen nicht mit.', '{1702,1703}', 7287, 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=37', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7437, 17, 12, 'BE', 'Kitas mit zusätzlichem Fachpersonal für Sprachbildung stärken und den Personalzuschlag für Sprachförderung wieder einführen.', '{1702}', 7298, 2, 2, null, 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=37', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7438, 17, 12, 'BE', 'Personalzuschlag für Integrationskitas erhöhen.', '{1702}', 7298, 2, 2, null, 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=37', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7439, 17, 13, 'BE', 'Allen Familien zum ersten Geburtstag automatisch einen Kitagutschein mit Zugang zu Beratung und Kitaplatzvermittlung zusenden.', '{1701}', 7282, 1, 3, null, 'Eine automatische Information und Vermittlung kann administrative Hürden senken. Sie erhöht das Platzangebot nicht und hilft nur, wenn passende Plätze verfügbar sind.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=182', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7440, 17, 13, 'BE', 'Kitaplätze transparent und diskriminierungsfrei vergeben.', '{1701}', 7283, 1, 3, null, 'Transparente Verfahren können Mehrfachanmeldungen und ungerechte Zugänge reduzieren. Ein digitales System schafft selbst keine zusätzlichen Betreuungsplätze.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=182', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7441, 17, 13, 'BE', 'Betriebskitas unterstützen und ergänzende Betreuung außerhalb der Öffnungszeiten für Alleinerziehende und Schichtarbeitende ausweiten.', '{1701}', 7277, 2, 2, null, 'Bedarfsgerechte Zeiten und Ersatzangebote können Versorgungslücken für Familien mit besonderen Arbeitszeiten abfedern. Personalbedarf, Nachfrage und Qualität begrenzen die flächendeckende Umsetzung.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=110', 'https://www.dji.de/themen/kinderbetreuung/eltern-wuenschen-sich-flexiblere-betreuungsangebote.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7442, 17, 13, 'BE', 'Kita-Platzausbau bei der Planung neuer Unterbringungsstandorte berücksichtigen.', '{1701}', 7274, 2, 2, null, 'Zusätzliche und gesicherte Plätze wirken unmittelbar gegen Angebotslücken; der tatsächliche Effekt hängt von Personalverfügbarkeit und regionaler Planung ab. Investitionen und laufende Kosten begrenzen das Tempo.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=146', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7443, 17, 13, 'BE', 'Betreuungsschlüssel in Kitas weiter verbessern.', '{1703}', 7287, 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=182', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7444, 17, 14, 'BE', 'Landesweites Fast-Track-Genehmigungsverfahren mit Bearbeitungsgarantie, um Verwaltungshindernisse beim Kita-Ausbau abzubauen.', '{1701}', 7273, 2, 3, null, 'Kürzere Verfahren können den Ausbau erleichtern, schaffen aber weder Bauflächen noch Personal. Verwaltungsvereinfachungen sind innerhalb einer Wahlperiode realistisch.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=7', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7445, 17, 14, 'BE', 'Freie Kitaträger bei der Finanzierung den landeseigenen Kitas gleichstellen.', '{1701}', 7275, 2, 2, null, 'Eine verlässliche Finanzierung kann Plätze erhalten und Ausbau ermöglichen. Der Effekt hängt davon ab, ob Mittel zusätzlich bereitgestellt und tatsächlich für Kapazitäten eingesetzt werden.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=7', 'https://www.dji.de/themen/kinderbetreuung/kita-personalbedarf.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7446, 17, 14, 'BE', 'Freien Kitaträgern Beiträge für zusätzliche pädagogische Leistungen außerhalb des Kitagutscheins ermöglichen.', '{1705}', 7323, 0, 3, null, 'Zusätzliche kostenpflichtige Leistungen verbessern die Bezahlbarkeit der Grundbetreuung nicht und können die Belastung von Familien erhöhen. Die Erlaubnis ist administrativ umsetzbar, wirkt aber dem Kostenziel nicht entgegen.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=7', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7447, 17, 14, 'BE', 'Sonderqualifikationen pädagogischer Fachkräfte in Kitas zusätzlich vergüten.', '{1702}', 7291, 2, 2, null, 'Bessere Bezahlung und Arbeitsbedingungen können die Attraktivität und Bindung von Fachkräften erhöhen. Der Fachkräftemangel und die Tarif- und Haushaltskosten begrenzen Geschwindigkeit und Reichweite.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=7', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7448, 17, 14, 'BE', 'Mittelbare pädagogische Arbeit vollständig anerkennen und in die Personalschlüssel einrechnen.', '{1703}', 7287, 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=6', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7449, 17, 14, 'BE', 'Fachkräftemangel im Erziehungssektor bekämpfen und Betreuungsschlüssel in Berliner Kitas deutlich verbessern.', '{1702,1703}', 7287, 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=8', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7450, 17, 14, 'BE', 'Kitagutschein automatisch mit der Geburtsurkunde ausstellen.', '{1701}', 7282, 1, 3, null, 'Eine automatische Information und Vermittlung kann administrative Hürden senken. Sie erhöht das Platzangebot nicht und hilft nur, wenn passende Plätze verfügbar sind.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=8', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7451, 17, 14, 'BE', 'Digitale Plattform für Kita- und Schulanmeldungen mit Echtzeit-Anmeldung und Mehrfachanmeldungen schaffen.', '{1701}', 7283, 1, 3, null, 'Transparente Verfahren können Mehrfachanmeldungen und ungerechte Zugänge reduzieren. Ein digitales System schafft selbst keine zusätzlichen Betreuungsplätze.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=113', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7452, 17, 14, 'BE', 'Über Anträge auf staatliche Leistungen einschließlich Kitagutscheinen binnen vier Wochen entscheiden und auszahlen.', '{1701}', 7285, 1, 3, null, 'Schnellere Bescheide erleichtern die Planung und beseitigen Verzögerungen im Verwaltungszugang. Sie schaffen keinen Platz, wenn das Angebot fehlt.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=113', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7453, 17, 14, 'BE', 'Dauerhaft ausreichend Kita- und Tagespflegeplätze mit flexibleren Öffnungszeiten, Notfallangeboten und 24-Stunden-Kitas schaffen.', '{1701}', 7277, 2, 2, null, 'Bedarfsgerechte Zeiten und Ersatzangebote können Versorgungslücken für Familien mit besonderen Arbeitszeiten abfedern. Personalbedarf, Nachfrage und Qualität begrenzen die flächendeckende Umsetzung.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=113', 'https://www.dji.de/themen/kinderbetreuung/eltern-wuenschen-sich-flexiblere-betreuungsangebote.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7454, 17, 14, 'BE', 'Kinderbetreuung zu Hause für Menschen im Schichtdienst staatlich unterstützen.', '{1701}', 7277, 2, 2, null, 'Bedarfsgerechte Zeiten und Ersatzangebote können Versorgungslücken für Familien mit besonderen Arbeitszeiten abfedern. Personalbedarf, Nachfrage und Qualität begrenzen die flächendeckende Umsetzung.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=113', 'https://www.dji.de/themen/kinderbetreuung/eltern-wuenschen-sich-flexiblere-betreuungsangebote.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7455, 17, 14, 'BE', 'Mobilen Kinderbetreuungsservice für Eltern mit besonderen Arbeitszeiten (MoKiS) deutlich ausbauen.', '{1701}', 7277, 2, 2, null, 'Bedarfsgerechte Zeiten und Ersatzangebote können Versorgungslücken für Familien mit besonderen Arbeitszeiten abfedern. Personalbedarf, Nachfrage und Qualität begrenzen die flächendeckende Umsetzung.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=113', 'https://www.dji.de/themen/kinderbetreuung/eltern-wuenschen-sich-flexiblere-betreuungsangebote.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7456, 17, 15, 'BE', 'Landeserziehungsgeld für Kinder unter drei Jahren in Höhe der vergleichbaren Kosten eines Kita-Platzes einführen.', '{1705}', 7309, 1, 2, null, 'Ein Geldbetrag kann Familien finanziell entlasten, sichert aber keinen Kita-Platz und kann die Nachfrage nach Betreuung sogar senken. Die Kosten hängen von Anspruch und Leistungshöhe ab.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=59', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7457, 17, 15, 'BE', 'Kostenfreiheit der Kita beibehalten.', '{1705}', 7302, 2, 2, null, 'Beitragsfreiheit entlastet Familien und kann die Nutzung besonders bei jüngeren Kindern erhöhen. Sie schafft zusätzliche Nachfrage und kann Mittel binden, die sonst für Qualität oder Plätze verfügbar wären.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=59', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7458, 17, 15, 'BE', 'Angebot an Kita-Plätzen erhalten und bedarfsgerecht ausbauen.', '{1701}', 7272, 2, 2, null, 'Ein erfüllter Anspruch verbessert den Zugang direkt, setzt aber ausreichende Plätze und Personal voraus. Die Umsetzung hängt deshalb von regionaler Kapazität und Finanzierung ab.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=60', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7459, 17, 15, 'BE', '„Blaulicht“-Kita für Polizei, Feuerwehr und Rettungsdienste schaffen; kleine und mittelgroße Kita-Träger sowie Betriebskindergärten fördern.', '{1701}', 7279, 2, 2, null, 'Betriebskitas schaffen zusätzliche Plätze und können Arbeitszeiten besser abdecken. Sie erreichen nicht alle Familien und benötigen Personal sowie tragfähige Trägerfinanzierung.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=60', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7460, 17, 15, 'BE', 'Bestehende Hochschul-Kitas ausbauen.', '{1701}', 7274, 2, 2, null, 'Zusätzliche und gesicherte Plätze wirken unmittelbar gegen Angebotslücken; der tatsächliche Effekt hängt von Personalverfügbarkeit und regionaler Planung ab. Investitionen und laufende Kosten begrenzen das Tempo.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=37', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7461, 17, 15, 'BE', 'Betreuungsschlüssel erhöhen und längere Öffnungszeiten für Eltern mit besonderen Arbeitszeiten ermöglichen.', '{1702,1703}', 7287, 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=60', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7462, 17, 16, 'BE', 'Personalschlüssel verbessern; Ziel sind rechnerisch drei Kinder unter drei Jahren bzw. 7,5 Kinder über drei Jahren je Fachkraft.', '{1703}', 7286, 3, 2, null, 'Die konkreten Zielwerte setzen direkt an der Personalausstattung an, die pädagogische Interaktionen ermöglicht. Die Verbesserung ist wirksam, erfordert angesichts des Fachkräftemangels aber zusätzliche Personal- und Finanzressourcen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=184', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7463, 17, 16, 'BE', 'Fehlzeiten und mittelbare Arbeitszeiten in der Personalzumessung berücksichtigen; nur ausgebildete Fachkräfte voll auf den Personalschlüssel anrechnen.', '{1702,1703}', 7287, 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=184', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7464, 17, 16, 'BE', 'Geltende Personalzuschläge mit Fachwelt und Praxis prüfen, öffnen und verbessern.', '{1702,1703}', 7298, 2, 2, null, 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=184', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7465, 17, 16, 'BE', 'Gesundheits-, Lärm- und Hitzeschutz in allen Kitas einführen, um das Arbeitsfeld für Fachkräfte attraktiv zu halten.', '{1702}', 7316, 1, 2, null, 'Bessere Arbeitsbedingungen können Belastungen mindern und die Bindung von Personal unterstützen. Der direkte Beitrag zu mehr verfügbaren Betreuungsstunden ist begrenzt und nicht gut untersucht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=185', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7466, 17, 16, 'BE', 'Modellprogramm Kita-Sozialarbeit erhalten und ausweiten, mittelfristig für zehn Prozent der Kitakinder, langfristig flächendeckend.', '{1702}', 7298, 2, 2, null, 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=185', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7467, 17, 16, 'BE', 'Bestehende Kita-Plätze durch planvolle Sanierungen sichern.', '{1701}', 7274, 2, 2, null, 'Zusätzliche und gesicherte Plätze wirken unmittelbar gegen Angebotslücken; der tatsächliche Effekt hängt von Personalverfügbarkeit und regionaler Planung ab. Investitionen und laufende Kosten begrenzen das Tempo.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=185', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7468, 17, 16, 'BE', 'Raum und Personal trotz sinkender Kinderzahlen im Kita-System halten.', '{1701,1702}', 7276, 2, 3, null, 'Kleinräumige Planung kann Plätze besser an Bedarf und Bevölkerungsentwicklung anpassen. Sie behebt einen landesweiten Personal- oder Finanzmangel nicht allein.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=186', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7469, 17, 16, 'BE', 'Anteil der landeseigenen Kita-Betriebe am Platzangebot auf ein Drittel erhöhen.', '{1701}', 7275, 2, 2, null, 'Eine verlässliche Finanzierung kann Plätze erhalten und Ausbau ermöglichen. Der Effekt hängt davon ab, ob Mittel zusätzlich bereitgestellt und tatsächlich für Kapazitäten eingesetzt werden.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=186', 'https://www.dji.de/themen/kinderbetreuung/kita-personalbedarf.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7470, 17, 16, 'BE', 'Eigenanteil der Kitaträger an der Platzfinanzierung schrittweise abschmelzen.', '{1701}', 7275, 2, 2, null, 'Eine verlässliche Finanzierung kann Plätze erhalten und Ausbau ermöglichen. Der Effekt hängt davon ab, ob Mittel zusätzlich bereitgestellt und tatsächlich für Kapazitäten eingesetzt werden.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=186', 'https://www.dji.de/themen/kinderbetreuung/kita-personalbedarf.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7471, 17, 16, 'BE', 'Allen Familien zum ersten Geburtstag einen verständlichen, mehrsprachigen Kita-Gutschein zusenden und aufsuchende Sozialarbeit zum Abbau von Zugangshürden stärken.', '{1701}', 7282, 1, 3, null, 'Eine automatische Information und Vermittlung kann administrative Hürden senken. Sie erhöht das Platzangebot nicht und hilft nur, wenn passende Plätze verfügbar sind.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=187', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7472, 17, 16, 'BE', 'Jugendämtern Zugriff auf einen Teil der Kitaplätze geben und das Freihalten von Plätzen finanzieren.', '{1701}', 7284, 1, 2, null, 'Reservierte Plätze können einzelne Zugangsprobleme abfedern, verringern aber die Zahl regulär verfügbarer Plätze. Der Nutzen hängt von lokaler Nachfrage und verlässlicher Finanzierung ab.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=187', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7473, 17, 16, 'BE', 'Vergütung in der Kindertagespflege so bemessen, dass sie Lebenshaltungskosten und Mieten deckt.', '{1701}', 7299, 2, 2, null, 'Faire Entgelte, Beratung und klare Vereinbarungen können Tagespflegepersonen halten und zusätzliche Plätze ermöglichen. Die Zahl der erreichbaren Plätze bleibt von der Gewinnung und Bindung der Betreuungspersonen abhängig.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=187', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7474, 17, 16, 'BE', 'Verbesserten Kita-Betreuungsschlüssel ohne finanzielle Einbußen auf die Kindertagespflege übertragen.', '{1703}', 7300, 2, 2, null, 'Eine bessere Personalausstattung kann die Betreuungsqualität erhöhen. Eine Übertragung ohne Einkommensverluste erfordert zusätzliche Finanzierung und muss zur Struktur der Tagespflege passen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=187', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7475, 17, 16, 'BE', 'Ausreichend barrierefreie Kitaplätze in Wohnortnähe schaffen und Kitas mit heil-, sozial- und inklusionspädagogischen Fachkräften ausstatten.', '{1701,1702}', 7298, 2, 2, null, 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=188', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7476, 17, 16, 'BE', 'Gezielt für das Berufsfeld Kita werben und Quereinsteigende bis zum DQR-Niveau 6 qualifizieren.', '{1702}', 7293, 2, 2, null, 'Mehr Ausbildungsplätze, Praxisanteile und Quereinstiege können mittelfristig den Personalzugang verbessern. Fehlende Lehrkräfte, Räume und Ausbildungserfolg begrenzen den Zuwachs.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=189', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7477, 17, 16, 'BE', 'Qualitätsinitiative für die Ausbildung starten und den Anteil staatlicher Schulen an der Erzieher*innenausbildung erhöhen.', '{1702}', 7293, 2, 2, null, 'Mehr Ausbildungsplätze, Praxisanteile und Quereinstiege können mittelfristig den Personalzugang verbessern. Fehlende Lehrkräfte, Räume und Ausbildungserfolg begrenzen den Zuwachs.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=189', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7478, 17, 16, 'BE', 'Praxisstunden in der Ausbildung vergüten und ausdrückliche Ausbildungsverträge einführen.', '{1702}', 7294, 2, 2, null, 'Vergütung kann den Zugang zur Ausbildung erleichtern und die Zahl der Auszubildenden erhöhen. Ein unmittelbarer Effekt auf verfügbare Fachkräfte entsteht erst nach Ausbildungsabschluss.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=189', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7479, 17, 16, 'BE', 'Gebührenfreiheit der Bildung von der Kita bis zur Hochschule als Grundsatz beibehalten.', '{1705}', 7302, 2, 2, null, 'Beitragsfreiheit entlastet Familien und kann die Nutzung besonders bei jüngeren Kindern erhöhen. Sie schafft zusätzliche Nachfrage und kann Mittel binden, die sonst für Qualität oder Plätze verfügbar wären.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=153', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7480, 17, 16, 'BE', 'Verpflichtende Zusatzzahlungen über Kitafördervereine zurückweisen.', '{1705}', 7311, 1, 3, null, 'Das Verhindern verpflichtender Zusatzforderungen kann unerwartete Kosten begrenzen. Es senkt nicht automatisch die regulären Elternbeiträge und muss mit der Finanzierung zusätzlicher Leistungen vereinbar sein.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=187', null, 'offen', '2026-10-01', false, true, 'blind'),
  (8564, 17, 18, null, 'Betreuungsangebot für Kinder deutlich ausbauen, damit niemand wegen fehlender Plätze auf Erwerbsarbeit verzichten muss', '{1701}', 7280, 2, 2, null, 'Investitionshilfen können zusätzliche Plätze und erreichbare Angebote ermöglichen. Die Wirkung hängt von kommunaler Planung, Kofinanzierung und verfügbarem Personal ab.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=52', 'https://www.dji.de/themen/kinderbetreuung/kita-personalbedarf.html', 'belegt', '2026-10-07', false, true, 'blind'),
  (8565, 17, 18, null, 'Bundesweite digitale Plattform zur Vergabe von Kita-Plätzen, die auch private Einrichtungen und Tageseltern einbindet und freie Plätze zeigt', '{1701}', 8563, 1, 2, null, 'Zentrale digitale Vergabe beschleunigt das Verfahren, macht es fairer und zeigt den tatsächlichen Bedarf. Sie schafft keine zusätzlichen Plätze; die Vergabe liegt bei Kommunen und Trägern, deren Anbindung der Bund nicht allein regelt.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=108', 'https://www.bertelsmann-stiftung.de/de/themen/aktuelle-meldungen/2023/juni/schneller-fairer-und-transparenter-zum-kita-platz-wie-ein-algorithmus-kommunen-helfen-kann', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8566, 17, 18, null, 'Tagespflege stärken durch geförderte gemeinsame Betreuungsräume für Tageseltern', '{1701}', 7301, 2, 2, null, 'Bundesunterstützung kann die Länder beim Erhalt und Ausbau ergänzender Betreuungsplätze unterstützen. Die konkrete Wirkung hängt von Umsetzung und dauerhafter Finanzierung vor Ort ab.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=108', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8567, 17, 18, null, 'Flexible Arbeitsplätze mit Kinderbetreuung durch Fachpersonal für Eltern ohne Kita-Platz oder bei kurzfristigem Betreuungsausfall', '{1704,1701}', null, 1, 2, null, 'Arbeitsplätze mit Betreuung können bei Ausfällen oder fehlendem Platz kurzfristig überbrücken; es gibt Praxisbeispiele, aber kaum Auswertungen. Sie ersetzen keinen regulären Platz, brauchen selbst Fachpersonal, Träger und Finanzierung sind offen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=108', 'https://www.uni-heidelberg.de/presse/news07/2709backu.html', 'offen', '2026-10-07', false, true, 'blind'),
  (8568, 17, 18, null, 'Bundesweit einheitliche Betreuungsschlüssel und Höchstgrößen der Gruppen in Krippen und Kitas', '{1703}', 8560, 3, 1, null, 'Die Zielwerte entsprechen den fachlichen Empfehlungen und setzen direkt an der Personalausstattung an. Für eine bundesweite Umsetzung fehlen absehbar sehr viele Fachkräfte; Umsetzung durch die Länder und Finanzierung sind ungeklärt.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=108', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-07', false, true, 'blind'),
  (8569, 17, 18, null, 'Pädagogische Fachkräfte werden gleich wie Lehrkräfte bezahlt', '{1702}', 8561, 2, 1, null, 'Die meisten Fachkräfte halten ihr Gehalt für unangemessen; höhere Löhne können Berufswahl und Verbleib stärken. Frühere Lohnzuwächse schlossen die Lücke aber nicht; der Bund ist nicht Tarifpartei, die Kosten sind sehr hoch.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=109', 'https://www.diw.de/de/diw_01.c.817992.de/publikationen/wochenberichte/2021_19_1/erzieherinnen_empfinden_vielfache_belastungen_und_wenig_anerkennung.html', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8570, 17, 18, null, 'Finanzielle Unterstützung für pädagogische Fachkräfte während der Ausbildung', '{1702}', 7295, 2, 2, null, 'Bundesmittel für vergütete Ausbildung, Kapazitäten und Qualifizierung können den Ländern beim Aufbau des Personals helfen. Wirkung und Zeitbedarf hängen von Länderumsetzung und Ausbildungserfolg ab.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=109', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8571, 17, 18, null, 'Multiprofessionelle Teams entlasten pädagogische Fachkräfte in Kitas', '{1702}', 8562, 2, 2, null, 'Zusätzliche Kräfte für Sprache, Verwaltung und Unterstützung können Fachkräfte entlasten; Entlastung durch Verwaltungskräfte wird empfohlen. Die Wirkung ist kaum untersucht, Ehrenamtliche ersetzen keine Fachkräfte, der Bund kann nur fördern.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=108', 'https://www.bertelsmann-stiftung.de/en/themen/aktuelle-meldungen/2023/november/mehr-plaetze-und-bessere-qualitaet-in-kitas-bis-2030-wenn-jetzt-entschlossen-gehandelt-wird', 'offen', '2026-10-07', false, true, 'blind'),
  (8572, 17, 18, null, 'Tagespflege, Krippen- und Kita-Plätze ab der Geburt bundesweit gebührenfrei', '{1705}', 7303, 2, 2, null, 'Geringere Beiträge entlasten Familien und können den Zugang erleichtern, beseitigen aber nicht alle Zusatzkosten. Mehr Nachfrage kann bei knappen Plätzen den Zugang erschweren, wenn der Ausbau nicht Schritt hält.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=105', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8607, 17, 18, 'BE', 'Gesetzliche Zielgrößen für den Betreuungsschlüssel in Krippe und Kita', '{1703}', 7286, 3, 2, null, 'Die konkreten Zielwerte setzen direkt an der Personalausstattung an, die pädagogische Interaktionen ermöglicht. Die Verbesserung ist wirksam, erfordert angesichts des Fachkräftemangels aber zusätzliche Personal- und Finanzressourcen.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=44', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-08', false, true, 'blind'),
  (8608, 17, 18, 'BE', 'Ausbildung und Qualifizierungswege ausbauen, Quereinstieg besser strukturieren, ausländische Abschlüsse schneller anerkennen', '{1702}', 7293, 2, 2, null, 'Mehr Ausbildungsplätze, Praxisanteile und Quereinstiege können mittelfristig den Personalzugang verbessern. Fehlende Lehrkräfte, Räume und Ausbildungserfolg begrenzen den Zuwachs.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=44', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8609, 17, 18, 'BE', 'Multiprofessionelle Teams in Kitas stärken, um Fachkräfte zu entlasten', '{1702}', 7298, 2, 2, null, 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=44', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8610, 17, 18, 'BE', 'Vorrang beim Kita-Platzausbau für Quartiere mit hohem Bedarf', '{1701}', 7276, 2, 3, null, 'Kleinräumige Planung kann Plätze besser an Bedarf und Bevölkerungsentwicklung anpassen. Sie behebt einen landesweiten Personal- oder Finanzmangel nicht allein.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=45', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8611, 17, 18, 'MV', 'Beitragsfreiheit der Kitas langfristig absichern, unabhängig vom Einkommen der Eltern.', '{1705}', 7302, 2, 2, null, 'Beitragsfreiheit entlastet Familien und kann die Nutzung besonders bei jüngeren Kindern erhöhen. Sie schafft zusätzliche Nachfrage und kann Mittel binden, die sonst für Qualität oder Plätze verfügbar wären.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=9', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8612, 17, 18, 'MV', 'Besserer Betreuungsschlüssel mit mehr pädagogischem Personal pro Gruppe sowie bessere Arbeitsbedingungen und angemessene Vergütung.', '{1702,1703}', 7287, 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=9', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-08', false, true, 'blind'),
  (8613, 17, 18, 'ST', 'Mehr pädagogisches Personal und Objekt- statt Subjektfinanzierung, um den Betreuungsschlüssel zu verbessern.', '{1703,1702}', 7287, 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=14', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-08', false, true, 'blind'),
  (8614, 17, 18, 'ST', 'Erzieherinnen und Erzieher höher und verlässlicher bezahlen.', '{1702}', 7291, 2, 2, null, 'Bessere Bezahlung und Arbeitsbedingungen können die Attraktivität und Bindung von Fachkräften erhöhen. Der Fachkräftemangel und die Tarif- und Haushaltskosten begrenzen Geschwindigkeit und Reichweite.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=14', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8615, 17, 18, 'ST', 'Sechs Stunden tägliche Kita-Betreuung landesweit kostenfrei; darüber hinaus Beiträge nach Elterneinkommen gestaffelt.', '{1705}', 7302, 2, 2, null, 'Beitragsfreiheit entlastet Familien und kann die Nutzung besonders bei jüngeren Kindern erhöhen. Sie schafft zusätzliche Nachfrage und kann Mittel binden, die sonst für Qualität oder Plätze verfügbar wären.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=14', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-08', false, true, 'blind');

